
const enc = new TextEncoder();

function json(data,status=200,headers={}) {
  return new Response(JSON.stringify(data), {status, headers:{"content-type":"application/json; charset=utf-8",...headers}});
}
function cookie(name,value,maxAge=2592000){
  return `${name}=${value}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${maxAge}`;
}
function parseCookies(req){
  const out={}; (req.headers.get("cookie")||"").split(";").forEach(p=>{const i=p.indexOf("="); if(i>0) out[p.slice(0,i).trim()]=p.slice(i+1).trim()}); return out;
}
function hex(buf){return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function sha256(s){return hex(await crypto.subtle.digest("SHA-256",enc.encode(s)))}
async function pbkdf2(password,salt,iterations=100000){
  const key=await crypto.subtle.importKey("raw",enc.encode(password),"PBKDF2",false,["deriveBits"]);
  return hex(await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:enc.encode(salt),iterations},key,256));
}
async function verifyPassword(password, stored){
  const [kind,it,salt,hash]=String(stored||"").split("$");
  if(kind!=="pbkdf2") return false;
  return (await pbkdf2(password,salt,Number(it)))===hash;
}
async function session(req,env){
  const token=parseCookies(req).pr_session; if(!token) return null;
  const h=await sha256(token);
  return env.DB.prepare(`SELECT s.email,s.expires_at,u.role,u.license_expires_at,u.suspended
    FROM pr_sessions s JOIN pr_users u ON u.email=s.email
    WHERE s.token_hash=? AND s.expires_at>datetime('now')`).bind(h).first();
}
async function requireAdmin(req,env){
  const s=await session(req,env); return s&&s.role==="admin"?s:null;
}
async function audit(env,email,action,detail=""){
  try{await env.DB.prepare("INSERT INTO pr_audit(email,action,detail,created_at) VALUES(?,?,?,datetime('now'))").bind(email||"",action,detail).run()}catch{}
}
function b64bytes(s){
  const bin=atob(s), a=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) a[i]=bin.charCodeAt(i);
  return a;
}

