const AUTH_JS = "\n(() => {\n  const gate = document.getElementById(\"auth-gate\");\n  const form = document.getElementById(\"login-form\");\n  const msg = document.getElementById(\"auth-message\");\n  function deviceId(){\n    let id=localStorage.getItem(\"pr_device_id\");\n    if(!id){ id=crypto.randomUUID(); localStorage.setItem(\"pr_device_id\",id); }\n    return id;\n  }\n  async function api(path, options={}){\n    const headers = Object.assign({\"content-type\":\"application/json\"}, options.headers||{});\n    return fetch(path, Object.assign({credentials:\"include\",headers}, options));\n  }\n  async function check(){\n    try{\n      const r=await api(\"/api/me\",{method:\"GET\",headers:{}});\n      if(r.ok){ gate.classList.add(\"hidden\"); return; }\n    }catch(e){}\n    gate.classList.remove(\"hidden\");\n  }\n  form.addEventListener(\"submit\", async e=>{\n    e.preventDefault(); msg.textContent=\"Verifica licenza\u2026\";\n    const r=await api(\"/api/login\",{method:\"POST\",body:JSON.stringify({\n      email:document.getElementById(\"login-email\").value.trim().toLowerCase(),\n      password:document.getElementById(\"login-password\").value,\n      device_id:deviceId()\n    })});\n    const d=await r.json().catch(()=>({}));\n    if(r.ok){ msg.textContent=\"Accesso riuscito.\"; gate.classList.add(\"hidden\"); }\n    else msg.textContent=d.error||\"Accesso non riuscito.\";\n  });\n  check();\n})();\n";
