const ADMIN_HTML = "<!doctype html>\n<html lang=\"it\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <title>ProResize Admin</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <style>\n    body{background:#171719;color:#fff;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;margin:0}\n    .admin-wrap{max-width:760px;margin:0 auto;padding:24px}\n    .admin-card{background:#242428;border:1px solid #3a3a40;border-radius:24px;padding:20px;margin:16px 0}\n    .admin-card h1,.admin-card h2{margin-top:0}\n    .admin-card label{display:block;margin:12px 0;font-weight:700}\n    .admin-card input,.admin-card select{width:100%;box-sizing:border-box;margin-top:6px;padding:13px;border-radius:12px;border:1px solid #4b4b55;background:#171719;color:white;font-size:16px}\n    .admin-card button{padding:12px 16px;border:0;border-radius:12px;font-weight:800;font-size:15px;margin:6px 6px 6px 0}\n    .primary{background:#fff;color:#111}\n    .danger{background:#6b2222;color:#fff}\n    .secondary{background:#3a3a40;color:#fff}\n    .muted{color:#aaa}\n    .user{border-top:1px solid #3a3a40;padding:14px 0}\n    .user:first-child{border-top:0}\n    .row{display:flex;gap:10px;flex-wrap:wrap}\n    .row>*{flex:1 1 180px}\n    .hidden{display:none!important}\n    #msg{min-height:22px}\n  </style>\n</head>\n<body>\n<div class=\"admin-wrap\">\n  <div class=\"admin-card\">\n    <h1>ProResize Admin</h1>\n    <p class=\"muted\">Gestione licenze, scadenze e dispositivo autorizzato.</p>\n    <p id=\"msg\"></p>\n  </div>\n\n  <section id=\"setup\" class=\"admin-card hidden\">\n    <h2>Primo accesso amministratore</h2>\n    <label>Email amministratore<input id=\"setup-email\" type=\"email\"></label>\n    <label>Password amministratore<input id=\"setup-password\" type=\"password\" minlength=\"10\"></label>\n    <button id=\"setup-btn\" class=\"primary\">Crea amministratore</button>\n  </section>\n\n  <section id=\"login\" class=\"admin-card hidden\">\n    <h2>Accesso amministratore</h2>\n    <label>Email<input id=\"login-email\" type=\"email\"></label>\n    <label>Password<input id=\"login-password\" type=\"password\"></label>\n    <button id=\"login-btn\" class=\"primary\">Accedi</button>\n  </section>\n\n  <section id=\"panel\" class=\"hidden\">\n    <div class=\"admin-card\">\n      <h2>Aggiungi / rinnova cliente</h2>\n      <label>Email cliente<input id=\"user-email\" type=\"email\"></label>\n      <label>Password cliente<input id=\"user-password\" type=\"password\" minlength=\"8\"></label>\n      <div class=\"row\">\n        <label>Durata\n          <select id=\"user-months\">\n            <option value=\"1\">1 mese</option>\n            <option value=\"6\">6 mesi</option>\n            <option value=\"12\">1 anno</option>\n          </select>\n        </label>\n        <label>Oppure scadenza personalizzata<input id=\"user-expiry\" type=\"date\"></label>\n      </div>\n      <button id=\"save-user\" class=\"primary\">Salva licenza</button>\n      <button id=\"logout\" class=\"secondary\">Esci</button>\n    </div>\n\n    <div class=\"admin-card\">\n      <h2>Clienti</h2>\n      <div id=\"users\"><p class=\"muted\">Caricamento\u2026</p></div>\n    </div>\n  </section>\n</div>\n<script src=\"admin.js\"></script>\n</body>\n</html>\n";
const ADMIN_JS = "\nconst $=id=>document.getElementById(id);\nconst msg=t=>$(\"msg\").textContent=t||\"\";\n\nasync function api(path,options={}){\n  const o={credentials:\"include\",...options};\n  o.headers={...(options.body?{\"content-type\":\"application/json\"}:{}),...(options.headers||{})};\n  const r=await fetch(path,o);\n  const d=await r.json().catch(()=>({}));\n  return {r,d};\n}\nfunction show(id){$(\"setup\").classList.add(\"hidden\");$(\"login\").classList.add(\"hidden\");$(\"panel\").classList.add(\"hidden\");$(id).classList.remove(\"hidden\")}\nasync function boot(){\n  const me=await api(\"/api/me\");\n  if(me.r.ok && me.d.role===\"admin\"){show(\"panel\");await loadUsers();return}\n  const s=await api(\"/api/setup-status\");\n  show(s.d.needs_setup?\"setup\":\"login\");\n}\n$(\"setup-btn\").onclick=async()=>{\n  msg(\"Creazione amministratore\u2026\");\n  const {r,d}=await api(\"/api/setup\",{method:\"POST\",body:JSON.stringify({email:$(\"setup-email\").value.trim().toLowerCase(),password:$(\"setup-password\").value})});\n  if(!r.ok){msg(d.error||\"Errore\");return}\n  msg(\"Amministratore creato. Ora accedi.\");\n  $(\"login-email\").value=$(\"setup-email\").value.trim().toLowerCase();\n  show(\"login\");\n};\n$(\"login-btn\").onclick=async()=>{\n  msg(\"Accesso\u2026\");\n  let did=localStorage.getItem(\"pr_admin_device_id\");\n  if(!did){did=crypto.randomUUID();localStorage.setItem(\"pr_admin_device_id\",did)}\n  const {r,d}=await api(\"/api/login\",{method:\"POST\",body:JSON.stringify({email:$(\"login-email\").value.trim().toLowerCase(),password:$(\"login-password\").value,device_id:did})});\n  if(!r.ok||d.role!==\"admin\"){msg(d.error||\"Accesso non autorizzato\");return}\n  msg(\"\");show(\"panel\");await loadUsers();\n};\n$(\"save-user\").onclick=async()=>{\n  const body={email:$(\"user-email\").value.trim().toLowerCase(),password:$(\"user-password\").value};\n  const custom=$(\"user-expiry\").value;\n  if(custom) body.expires_at=new Date(custom+\"T23:59:59Z\").toISOString(); else body.months=Number($(\"user-months\").value);\n  msg(\"Salvataggio licenza\u2026\");\n  const {r,d}=await api(\"/api/admin/users\",{method:\"POST\",body:JSON.stringify(body)});\n  if(!r.ok){msg(d.error||\"Errore\");return}\n  msg(\"Licenza salvata.\");\n  $(\"user-email\").value=\"\";$(\"user-password\").value=\"\";$(\"user-expiry\").value=\"\";\n  await loadUsers();\n};\n$(\"logout\").onclick=async()=>{await api(\"/api/logout\",{method:\"POST\"});location.reload()};\n\nasync function act(email,action){\n  const {r,d}=await api(\"/api/admin/users/\"+encodeURIComponent(email)+\"/\"+action,{method:\"POST\"});\n  msg(r.ok?\"Operazione completata.\":(d.error||\"Errore\"));\n  if(r.ok) await loadUsers();\n}\nasync function loadUsers(){\n  const {r,d}=await api(\"/api/admin/users\");\n  if(!r.ok){msg(d.error||\"Sessione scaduta\");show(\"login\");return}\n  const list=(d.users||[]).filter(u=>u.role!==\"admin\");\n  $(\"users\").innerHTML=list.length?list.map(u=>{\n    const exp=u.license_expires_at?new Date(u.license_expires_at).toLocaleDateString(\"it-IT\"):\"\u2014\";\n    return `<div class=\"user\">\n      <strong>${escapeHtml(u.email)}</strong><br>\n      <span class=\"muted\">Scadenza: ${exp} \u00b7 ${u.suspended?\"SOSPESA\":\"Attiva\"} \u00b7 Dispositivo: ${u.device_bound?\"associato\":\"libero\"}</span><br>\n      <button class=\"secondary\" onclick=\"act('${jsq(u.email)}','reset-device')\">Reset dispositivo</button>\n      ${u.suspended?`<button class=\"primary\" onclick=\"act('${jsq(u.email)}','activate')\">Riattiva</button>`:`<button class=\"danger\" onclick=\"act('${jsq(u.email)}','suspend')\">Sospendi</button>`}\n    </div>`;\n  }).join(\"\"):'<p class=\"muted\">Nessun cliente ancora.</p>';\n}\nfunction escapeHtml(s){return String(s).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]))}\nfunction jsq(s){return String(s).replace(/\\\\/g,\"\\\\\\\\\").replace(/'/g,\"\\\\'\")}\nboot();\n";
const LOGO_B64 = "";

export default {
 async fetch(req,env){
  const url=new URL(req.url), p=url.pathname;

  if(p==="/api/setup-status"){
    const row=await env.DB.prepare("SELECT COUNT(*) n FROM pr_users WHERE role='admin'").first();
    return json({needs_setup:Number(row?.n||0)===0});
  }

  if(p==="/api/setup" && req.method==="POST"){
    const count=await env.DB.prepare("SELECT COUNT(*) n FROM pr_users WHERE role='admin'").first();
    if(Number(count?.n||0)!==0) return json({error:"Configurazione già completata"},403);
    const {email,password}=await req.json();
    if(!email||!password||password.length<10) return json({error:"Usa email valida e password di almeno 10 caratteri"},400);
    const salt=crypto.randomUUID(), it=100000, hash=await pbkdf2(password,salt,it);
    await env.DB.prepare(`INSERT INTO pr_users(email,password_hash,role,suspended,created_at)
      VALUES(?,?, 'admin',0,datetime('now'))`).bind(email.toLowerCase(),`pbkdf2$${it}$${salt}$${hash}`).run();
    await audit(env,email,"admin_setup");
    return json({ok:true});
  }

  if(p==="/api/login" && req.method==="POST"){
    const {email,password,device_id}=await req.json();
    const e=String(email||"").toLowerCase();
    const u=await env.DB.prepare("SELECT * FROM pr_users WHERE email=?").bind(e).first();
    if(!u || !(await verifyPassword(password,u.password_hash))) return json({error:"Email o password non corretti"},401);
    if(Number(u.suspended)) return json({error:"Account sospeso"},403);
    if(u.role!=="admin" && (!u.license_expires_at || new Date(u.license_expires_at)<=new Date())) return json({error:"Licenza scaduta"},403);

    const dh=await sha256(String(device_id||""));
    if(u.role!=="admin"){
      if(u.device_hash && u.device_hash!==dh) return json({error:"Licenza già associata a un altro dispositivo"},403);
      if(!u.device_hash) await env.DB.prepare("UPDATE pr_users SET device_hash=? WHERE email=?").bind(dh,e).run();
    }
    const token=crypto.randomUUID()+crypto.randomUUID(), th=await sha256(token);
    await env.DB.prepare("DELETE FROM pr_sessions WHERE email=?").bind(e).run();
    await env.DB.prepare("INSERT INTO pr_sessions(token_hash,email,expires_at,created_at) VALUES(?,?,datetime('now','+30 days'),datetime('now'))").bind(th,e).run();
    await audit(env,e,"login");
    return json({ok:true,role:u.role,expires_at:u.license_expires_at},200,{"set-cookie":cookie("pr_session",token)});
  }

  if(p==="/api/me"){
    const s=await session(req,env);
    if(!s) return json({error:"Non autenticato"},401);
    if(Number(s.suspended)) return json({error:"Account sospeso"},403);
    if(s.role!=="admin" && (!s.license_expires_at || new Date(s.license_expires_at)<=new Date())) return json({error:"Licenza scaduta"},403);
    return json({ok:true,email:s.email,role:s.role,expires_at:s.license_expires_at});
  }

  if(p==="/api/logout" && req.method==="POST"){
    const token=parseCookies(req).pr_session;
    if(token) await env.DB.prepare("DELETE FROM pr_sessions WHERE token_hash=?").bind(await sha256(token)).run();
    return json({ok:true},200,{"set-cookie":cookie("pr_session","",0)});
  }

  if(p==="/api/admin/users" && req.method==="GET"){
    if(!await requireAdmin(req,env)) return json({error:"Non autorizzato"},403);
    const {results}=await env.DB.prepare("SELECT email,role,license_expires_at,suspended,device_hash IS NOT NULL AS device_bound,created_at FROM pr_users ORDER BY created_at DESC").all();
    return json({users:results});
  }

  if(p==="/api/admin/users" && req.method==="POST"){
    const a=await requireAdmin(req,env); if(!a) return json({error:"Non autorizzato"},403);
    const {email,password,months,expires_at}=await req.json(), e=String(email||"").toLowerCase();
    if(!e||!password||password.length<8) return json({error:"Email e password (minimo 8 caratteri) richieste"},400);
    let exp=expires_at||null;
    if(!exp){
      const m=[1,6,12].includes(Number(months))?Number(months):1;
      const d=new Date(); d.setMonth(d.getMonth()+m); exp=d.toISOString();
    }
    const salt=crypto.randomUUID(),it=100000,hash=await pbkdf2(password,salt,it);
    await env.DB.prepare(`INSERT INTO pr_users(email,password_hash,role,license_expires_at,suspended,created_at)
      VALUES(?,?, 'user',?,0,datetime('now'))
      ON CONFLICT(email) DO UPDATE SET password_hash=excluded.password_hash,license_expires_at=excluded.license_expires_at,suspended=0`)
      .bind(e,`pbkdf2$${it}$${salt}$${hash}`,exp).run();
    await audit(env,a.email,"user_upsert",e+" -> "+exp);
    return json({ok:true,email:e,expires_at:exp});
  }

  const m=p.match(/^\/api\/admin\/users\/([^/]+)\/(reset-device|suspend|activate)$/);
  if(m && req.method==="POST"){
    const a=await requireAdmin(req,env); if(!a) return json({error:"Non autorizzato"},403);
    const e=decodeURIComponent(m[1]).toLowerCase(), action=m[2];
    if(action==="reset-device") await env.DB.prepare("UPDATE pr_users SET device_hash=NULL WHERE email=?").bind(e).run();
    if(action==="suspend") await env.DB.prepare("UPDATE pr_users SET suspended=1 WHERE email=?").bind(e).run();
    if(action==="activate") await env.DB.prepare("UPDATE pr_users SET suspended=0 WHERE email=?").bind(e).run();
    await env.DB.prepare("DELETE FROM pr_sessions WHERE email=?").bind(e).run();
    await audit(env,a.email,action,e);
    return json({ok:true});
  }

  // Embedded static app files
  if(p==="/" || p==="/index.html") return new Response(INDEX_HTML,{headers:{"content-type":"text/html; charset=utf-8"}});
  if(p==="/app.js") return new Response(APP_JS,{headers:{"content-type":"application/javascript; charset=utf-8"}});
  if(p==="/auth.js") return new Response(AUTH_JS,{headers:{"content-type":"application/javascript; charset=utf-8"}});
  if(p==="/style.css") return new Response(STYLE_CSS,{headers:{"content-type":"text/css; charset=utf-8"}});
  if(p==="/admin.html") return new Response(ADMIN_HTML,{headers:{"content-type":"text/html; charset=utf-8"}});
  if(p==="/admin.js") return new Response(ADMIN_JS,{headers:{"content-type":"application/javascript; charset=utf-8"}});
  if(p==="/proresize-logo.jpeg") return new Response(b64bytes(LOGO_B64),{headers:{"content-type":"image/jpeg","cache-control":"public,max-age=86400"}});
  return new Response("Not found",{status:404});
 }
};
